"""English copy, reviewed against the app implementation on 2026-11-15."""

def section(id, title, body): return {'id': id, 'title': title, 'body': body}
def doc(title, description, lead, sections): return dict(title=title, description=description, lead=lead, sections=sections)

PAGES = {}
PAGES['privacy-policy'] = doc('Privacy Policy', 'How Pattern handles your files, permissions, backups, and sharing.',
    'Your content starts on your device. Cloud backup and sharing are choices you make for each vault.', [
section('scope', 'Who this policy covers', '''<p>This policy explains how {{publisher}} (“we”) handles information in the Pattern app for iPhone and iPad. You do not need a Pattern account. Optional iCloud features require an Apple Account signed in to iCloud.</p><p>For privacy questions or requests, contact {{contact}}. Developer location: {{country}}.</p>'''),
section('at-a-glance', 'At a glance', '''<ul><li>Files you import, capture, or create are stored in the app’s local storage.</li><li>The app has no advertising network, third-party analytics SDK, or cross-app tracking integration.</li><li>We do not sell your personal information or share it for targeted advertising.</li><li>Optional backups and shared copies are encrypted on your device before being uploaded to Apple’s iCloud services.</li><li>Patterns and recovery phrases are not sent to a developer-operated account server. Pattern has no such server.</li></ul>'''),
section('local-data', 'Information stored on your device', '''<div class="table-wrap"><table><thead><tr><th>Information</th><th>Why Pattern uses it</th></tr></thead><tbody><tr><td>Photos, videos, memos, and documents; thumbnails and previews</td><td>Store and display the content you choose.</td></tr><tr><td>Vault and folder names, filenames, item types, dates, sizes, and folder membership</td><td>Organize, search, sort, and restore your library.</td></tr><tr><td>Pattern and recovery-phrase verifiers, security settings, and failed-attempt state</td><td>Control access and support recovery.</td></tr><tr><td>Backup and sharing secrets, iCloud record identifiers, recipient labels, and shared-vault open counts</td><td>Perform the optional cloud functions you enable and enforce access settings.</td></tr><tr><td>App preferences, onboarding state, and special-offer timing</td><td>Remember settings and display applicable purchase offers.</td></tr></tbody></table></div><p>Original files can contain embedded metadata, including dates or location information added by the source camera. Pattern does not promise to remove that metadata when importing, exporting, backing up, or sharing a file. The app does not request access to your device’s location.</p><p>Raw unlock patterns are not retained. Ordinary recovery setup stores a verifier rather than a readable recovery phrase. A new phrase generated by duress mode is temporarily retained inside the protected credential record until you acknowledge saving it.</p>'''),
section('protection', 'How protection works', '''<p>Local files use iOS Data Protection with complete file protection. The pattern controls access within the app; local media is <strong>not encrypted with a key derived from your pattern</strong>. The credential record has an additional layer of AES-256-GCM encryption tied to the app installation.</p><p>Encrypted iCloud backups, portable backup files, and shared archives use AES-256-GCM. Their recovery and sharing secrets serve different purposes from an unlock pattern. Pattern covers its content in the app switcher and requires a new unlock after backgrounding.</p><p>No app can guarantee security on a compromised device, prevent every screenshot or external photograph, or retrieve a secret that you have lost. See the <a href="manual.html#recovery">recovery guide</a> for how to keep a usable backup.</p>'''),
section('icloud', 'Optional iCloud backup', '''<p>Backup is off until you enable it for an owned vault. Pattern uploads an encrypted archive and encrypted vault metadata to your private CloudKit database. Your recovery phrase protects the secret needed to restore the archive; the raw phrase and archive secret are not uploaded as readable fields.</p><p>Apple operates the storage service and can process service information such as account-related identifiers, record identifiers, timestamps, transfer sizes, and connection information. Encryption of the content does not conceal all service metadata. Apple’s handling is described in its <a href="https://www.apple.com/legal/privacy/">Privacy Policy</a> and <a href="https://www.apple.com/legal/internet-services/icloud/en/terms.html">iCloud terms</a>.</p><p>Backups run while the relevant vault is open. There is one latest completed backup per configured vault, not a history of previous versions. This is separate from ordinary device backup and from iCloud Photos.</p>'''),
section('sharing', 'Sharing a vault', '''<p>When you create a share, Pattern makes an encrypted, read-only cloud copy for a recipient. An encrypted invitation is stored in CloudKit’s public database so another signed-in Apple Account can find it using the sharing phrase. That lookup record does not contain readable vault media or the raw phrase; account and record metadata can still be associated with it.</p><p>The person who first claims an invitation can access it through the Apple Account used for the claim. Send the phrase only to your intended recipient. A recipient can see the contents and embedded file metadata, and can export when you permit it. Even with exporting disabled, a recipient may photograph the screen or otherwise retain information they have seen.</p><p>Received content is cached locally. Opening it requires an online access check, with further checks while it remains open. Expiration, open limits, and capture controls are app rules, not a guarantee against copying. Revocation cannot remove a recipient’s separately saved copies.</p>'''),
section('permissions', 'Permissions and actions you control', '''<ul><li><strong>Photos:</strong> the system picker supplies the items you select. Broader Photos access is requested when you choose to delete imported originals, after successful import and system confirmation. Saving or exporting through a system destination can require that destination’s permissions.</li><li><strong>Camera:</strong> used when you open the private camera. Captures stay in an app-private draft until you choose Use; the camera does not automatically save them to Photos.</li><li><strong>Microphone:</strong> requested for recording video with audio.</li><li><strong>Face ID or Touch ID:</strong> Apple’s biometric system returns an authentication result. Pattern does not receive your face scan, fingerprint, or biometric template.</li><li><strong>Files and share sheet:</strong> Pattern accesses selected documents or passes the files and phrases you choose to the destination you select. That destination’s handling then applies.</li><li><strong>Clipboard:</strong> phrase fields have an explicit Paste control; the app does not continuously read your clipboard. Phrase-copy actions use local-only clipboard items with an expiration.</li></ul><p>You can change system permissions in Settings. Refusing a permission limits its related feature rather than granting broader access to your content.</p>'''),
section('purchases', 'Purchases and diagnostics', '''<p>Apple handles payment. Pattern uses Apple’s StoreKit transaction and entitlement information to unlock purchased features, including product and transaction identifiers and purchase status. We do not receive your payment-card details through the app.</p><p>The current app has no custom analytics or crash-upload SDK. Apple may make app statistics and diagnostic reports available to developers according to your system settings and its policies. You can review Analytics &amp; Improvements in device Settings; see <a href="https://www.apple.com/legal/privacy/data/en/app-analytics/">Apple’s App Analytics &amp; Privacy notice</a>.</p>'''),
section('retention', 'Retention and deletion', '''<ul><li><strong>Local content:</strong> remains until you delete the items, delete their vault, or delete the app. Deleting a folder keeps its items in the vault. Deleting an item inside Pattern has no in-app trash or undo.</li><li><strong>Ordinary device backups:</strong> the app excludes local vault files and its installation key. Use Pattern’s encrypted backup options if you need a restorable copy.</li><li><strong>Cloud backup:</strong> choose Turn off and delete cloud backup to stop future uploads and request removal of the configured backup. The local vault remains.</li><li><strong>Vault deletion:</strong> removes local content and credentials. For an owned vault, it also queues removal of its configured cloud backup and owned shares. Removing a received vault removes your local copy, not the owner’s cloud copy.</li><li><strong>Pending cloud removal:</strong> deletion and revocation may wait for connectivity and the correct iCloud account. Keep Pattern installed and reopen it to complete pending work. Deleting the app can discard pending requests.</li><li><strong>App deletion:</strong> removes local files and the installation key. It does not itself delete completed iCloud backups, Photos originals, purchases, or files you exported elsewhere. Offloading the app is different: iOS keeps its documents and data.</li><li><strong>External copies:</strong> manage exported files, recipient copies, and Photos originals separately. Deleting an original in Photos can affect iCloud Photos and synced devices; Photos may retain it in Recently Deleted.</li></ul><p>Duress mode removes access credentials for other local vaults but leaves their files on disk. It is not secure erasure. It also changes recovery and backup behavior; read <a href="manual.html#duress">the duress explanation</a> before enabling it.</p><p>Apple and any destination service apply their own retention and deletion practices to data they process, including operational records and service backups.</p>'''),
section('support-rights', 'Support, requests, and your choices', '''<p>If you contact us, we process the email address, message, and attachments you choose to provide to respond, troubleshoot, and address privacy or security concerns. We retain support information only for as long as reasonably needed for those purposes or a legal obligation. We may use email and support service providers to handle that correspondence and disclose information where legally required.</p><p>Please do not send unlock patterns, recovery phrases, sharing phrases, or private vault files with a support request. We do not have a server-side copy that lets us reset your pattern or decrypt a lost backup for you.</p><p>Depending on your location, you may have rights to access, correct, delete, obtain a copy of, restrict, or object to processing of personal information, withdraw consent where applicable, or complain to your local privacy authority. Contact {{contact}} to exercise rights concerning information we hold. We may need proportionate verification. Local vault content is managed on your device; requests about Apple’s own processing should also be directed to Apple.</p>'''),
section('children-changes', 'Children and policy updates', '''<p>Pattern does not request a date of birth or create a separate child profile. Apple Account requirements and the app’s App Store age rating apply. Where local law requires a parent or guardian’s permission, obtain it before using the relevant services. A parent or guardian with a privacy concern may contact us.</p><p>We may update this policy when the app or our practices change. The date at the top identifies this version. Where required, we will provide additional notice or request consent before applying a material change. This policy concerns the app and support correspondence; additional services or tracking added to a website need their own appropriate disclosures.</p>''')])

PAGES['terms-of-use'] = doc('Terms of Use', 'The conditions for using Pattern and its optional cloud features.',
    'Understand your license, your responsibilities, and the limits of recovery and sharing.', [
section('agreement', 'About these terms', '''<p>These terms describe your use of Pattern, provided by {{publisher}} (“we”), based in {{country}}. Use Pattern only if you can accept the applicable terms, or have any parent or guardian permission required by law.</p><p>The app is distributed through Apple’s App Store. Its software license is governed by <a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple’s Standard Licensed Application End User License Agreement</a>, unless a different license is supplied with your App Store download. These terms explain Pattern’s features and use alongside that license; they do not replace Apple’s terms or override mandatory consumer rights. The <a href="privacy-policy.html">Privacy Policy</a> explains information handling.</p>'''),
section('service', 'What Pattern provides', '''<p>Pattern stores photos, videos, memos, and documents in separate local vaults opened with patterns. Optional functions include biometric access, encrypted backup files, iCloud backup, and read-only sharing. The current app requires iOS or iPadOS 26.2 or later; feature availability also depends on compatible hardware, permissions, storage, and Apple services.</p><p>The free version allows three owned vaults and five total items in each vault, including items in folders and all supported item types. Received shared vaults do not count toward the owned-vault limits. Pattern Pro removes these app limits and enables creating shares; device capacity and iCloud storage limits still apply.</p>'''),
section('purchases', 'Purchases, offers, and refunds', '''<p>Pattern Pro is a one-time, non-consumable in-app purchase, not a subscription. The regular purchase and any special offer unlock the same features. Price, currency, taxes, availability, and eligibility are those shown in Apple’s purchase flow. An offer may expire or be unavailable; no purchase is completed without Apple’s confirmation.</p><p>Use Restore purchases with the Apple Account that made the purchase. Restoring a purchase restores feature access, not your vault files. Pending, cancelled, or unverified transactions do not unlock Pro. A refund or revocation can remove paid access; the current app keeps existing local content available to view, export where allowed, or delete, while restricting new additions under free limits.</p><p>Apple handles App Store billing and refund requests. Eligibility depends on Apple’s rules and applicable law; see <a href="https://support.apple.com/en-us/118223">Apple’s refund instructions</a>. Nothing here excludes refund or other remedies that the law gives you. A one-time purchase does not promise indefinite availability of third-party services or a particular future device’s compatibility.</p>'''),
section('your-content', 'Your content and permitted use', '''<p>You retain your rights in the content you store. You authorize the processing needed to carry out the actions you choose, such as local storage, backup, export, and sharing; using Pattern does not grant us ownership of your files.</p><p>You are responsible for having the rights and any consent required to capture, store, or share content. Do not use Pattern to violate privacy, infringe intellectual property, exploit or abuse anyone, distribute unlawful material, gain unauthorized access, or interfere with the app or Apple’s services. Silent capture does not remove recording or consent requirements.</p><p>The app does not offer a public content feed or a public vault directory. Only share with people you intend to receive your content.</p>'''),
section('security-recovery', 'Patterns, recovery, and backups', '''<p>You are responsible for protecting your device, Apple Account, patterns, recovery phrases, and sharing phrases. Keep recovery information outside Pattern in a place you can access if the app or device is lost.</p><p>Local media uses iOS file protection and an app access lock, not media encryption derived from your pattern. Backup archives are encrypted separately. Security features reduce particular risks; they do not promise absolute secrecy, screenshot prevention, or protection on a compromised device.</p><p><strong>A recovery phrase alone cannot recreate deleted files.</strong> Restoration needs a completed encrypted cloud backup or an exported backup file and the phrase valid for that backup. Local vaults are excluded from ordinary device backups. Verify a completed backup before deleting Pattern, resetting a device, or changing devices. We cannot recover lost secrets or content for which no usable copy exists.</p>'''),
section('cloud-sharing', 'Cloud services and sharing', '''<p>iCloud backup and sharing depend on Apple, connectivity, the correct Apple Account, and available storage. Apple’s <a href="https://www.apple.com/legal/privacy/">Privacy Policy</a> and <a href="https://www.apple.com/legal/internet-services/icloud/en/terms.html">iCloud terms</a> also apply. Pattern’s backup runs while the vault is open, retains the latest completed version, and is not continuous background or two-way device synchronization.</p><p>Each sharing phrase creates a claim for one recipient Apple Account. The recipient’s vault is read-only and requires online access checks. Expiration, per-installation open limits, export controls, and capture-triggered locking cannot guarantee that content has not been copied. Revocation needs to reach iCloud and cannot erase files already exported, screenshots already taken, or external photographs.</p><p>Deleting the app is not a request to delete all cloud content. Follow the removal controls in the app and let pending requests complete before uninstalling.</p>'''),
section('duress', 'Duress and irreversible actions', '''<p><strong>Duress is an advanced, consequential feature.</strong> Enabling it arms the current vault’s pattern. Unlocking with that armed pattern keeps the selected dummy vault, or the triggering vault if there is no dummy, and removes access credentials for every other local vault. It generates a new recovery phrase for the surviving vault, stops backups and sharing on that installation, and queues owned-share revocations.</p><p>Other vault files remain on disk, but their previous patterns and phrases no longer open them in Pattern. Turning duress off does not undo this. A separately saved, usable encrypted backup may be restored explicitly. Duress is not cryptographic erasure, an emergency service, or a guarantee of concealment or personal safety. A failed Face ID or Touch ID check that opens a dummy vault does not itself activate duress.</p><p>Deleting items or a vault also has consequences described in the app. Read confirmations before proceeding and keep independent backups where needed.</p>'''),
section('availability-liability', 'Availability and your legal rights', '''<p>We aim to keep Pattern useful and reliable, but cannot promise uninterrupted operation, error-free software, successful recovery in every case, or uninterrupted Apple services. Updates may change features or compatibility. Where legally required, we will give notice of material changes affecting your rights.</p><p>Warranty, liability, license termination, and dispute provisions in the applicable App Store license continue to apply. These terms do not exclude liability that cannot lawfully be excluded, including protections that apply to consumers. They do not add a mandatory arbitration clause, waive collective remedies, or impose a different exclusive court.</p><p>You can stop using Pattern at any time. Export or back up what you need and remove cloud copies separately before deleting the app. Provisions that reasonably need to survive termination, such as content ownership and applicable liability rules, continue to apply.</p>'''),
section('contact-changes', 'Contact and changes', '''<p>Questions about these terms, support issues, or suspected misuse can be sent to {{contact}}. Do not send unlock patterns, recovery phrases, or sharing phrases. Remove private content from screenshots and send only the details needed to describe the issue.</p><p>The version date appears at the top. Material revisions will be handled with notice and consent where required by applicable law. Versions in all supported app languages are provided for convenience and accessibility; none limits rights granted by mandatory local law. If wording appears inconsistent, contact us for clarification.</p>''')])

PAGES['manual'] = doc('Manual', 'A practical guide to setting up and using Pattern.',
    'Start with a pattern. Keep a recovery phrase. Add the moments and files you want to keep private.', [
section('start', '1. Set up your first vault', '''<ol><li>Open Pattern and continue through, or skip, the introduction. Choose <strong>Create a new vault</strong>. If you already have a backup or an invitation, choose the restore or join option instead.</li><li>Choose a <strong>3 × 3, 4 × 4, or 5 × 5</strong> grid and name the vault.</li><li>Draw a pattern using at least four different dots, then repeat it. Dots crossed along the path are included automatically; a dot cannot be used twice in one gesture.</li><li>Use a generated 20-word recovery phrase, or create a custom phrase with at least eight words and 40 characters. Save it outside Pattern with <strong>Save to Notes</strong> or <strong>Copy phrase</strong>.</li><li>Repeat the full phrase and confirm that you saved it outside the app. You can close the purchase offers and continue with the free version.</li></ol><div class="callout"><strong>Keep the phrase somewhere you can reach without this device.</strong> A phrase stored only inside the vault cannot help you if that vault is unavailable. Switching apps during first-time setup preserves unfinished steps in memory; ending the app process can discard unfinished setup.</div><p>The app supports iPhone and iPad on iOS/iPadOS 26.2 or later. Interface labels follow the selected app language.</p>'''),
section('vaults', '2. Open and switch vaults', '''<p>Each pattern selects a different vault. From the library header, tap <strong>New vault</strong>, enter a name, and draw a new pattern twice. You cannot reuse a pattern already assigned to another vault. An unknown pattern never creates a vault automatically.</p><p>Tap the <strong>lock icon</strong> to return to the lock screen, then draw the other vault’s pattern. Pattern also locks after going into the background. A folder organizes items inside a vault; it does not have its own pattern or separate storage allowance.</p><p>The free version includes three owned vaults with five items each. Photos, videos, memos, and documents all count; items inside folders share the same allowance.</p>'''),
section('add', '3. Add photos, videos, memos, and documents', '''<p>Open the destination vault and, optionally, a folder. Tap <strong>Add</strong>:</p><ul><li><strong>Media:</strong> select photos or videos in the system picker. Pattern copies the selected items and reports any failures or skipped items.</li><li><strong>Memo:</strong> write a title and text, then save. Memos are stored as text files.</li><li><strong>Document:</strong> select files from Files or an available file provider. Pattern makes its own copies. Some formats can be stored even when a preview is unavailable.</li><li><strong>Camera:</strong> capture a new photo or video directly into a private draft.</li></ul><p>Imports do not automatically remove source files. After a successful Photos import, <strong>Delete originals from Photos</strong> is optional and requires permission and system confirmation. It affects the Photos library, including iCloud Photos and synced devices when enabled. Photos may keep deleted items in Recently Deleted. Pattern does not empty that collection.</p><p>The current Live Photo import saves its still image, not the motion component; Pattern declines automatic deletion of those Live Photo originals. Verify important imports before deleting sources.</p>'''),
section('camera', '4. Use the private camera', '''<ol><li>Choose <strong>Add → Camera</strong> and allow camera access. Microphone access is requested for video recording.</li><li>Choose Photo or Video and use the front/rear camera control as needed.</li><li>In Photo mode, tap the speaker control next to the camera switch. A crossed-out speaker selects silent photo capture on supported cameras.</li><li>Capture, then review. Choose <strong>Use</strong> to save into the current vault/folder, or <strong>Retake</strong> to discard the draft and return to the camera. Cancel or backgrounding discards an unconfirmed capture.</li></ol><p>Captures are not automatically added to Photos. Silent photos use a camera video frame and can have less detail than normal photos; support depends on the device and camera. The speaker setting does not mute audio in recorded videos. The camera review uses its own dark appearance.</p>'''),
section('organize', '5. Search, filter, and organize', '''<ul><li><strong>Search:</strong> enter part of an item or filename in the search field. Search works within the current library or folder, combines with the selected filter, and is not a search of text inside a document. Folder changes or adding content clear the search.</li><li><strong>Sort:</strong> tap the up/down-arrow icon. Choose import date, name, file date, largest first, or smallest first. File date uses available original metadata, with fallback dates when needed.</li><li><strong>Filter:</strong> tap the filter icon for All, Photos, Videos, Memos, or Documents.</li><li><strong>Select:</strong> tap the check-circle icon to select items, select all, move, export, or delete. Tap it again to finish selection.</li><li><strong>Folders:</strong> create, rename, recolor, or delete folders using the folder controls. Move selected items into a folder. Deleting a folder keeps its items in the vault.</li></ul><p>On wider iPad layouts, a folder sidebar provides navigation. Photos support zoom and paging; videos use native playback controls. Playback pauses when you leave a video or background the app.</p>'''),
section('export-delete', '6. Export and delete items', '''<p>Select the items and use the export action to open the system share sheet. Choose Files, another app, or an available destination. Exports are ordinary copies of the selected files, not encrypted Pattern backups. Their metadata may remain. For an encrypted archive, use <a href="#file-backup">File backup</a> instead.</p><p>Received shared vaults can export only if the owner allows it. Deleting items removes the app’s copies after confirmation and has no in-app trash. It does not delete Photos originals or previously exported copies.</p>'''),
section('recovery', '7. Patterns, recovery phrases, and grid size', '''<p>Open the gear icon for <strong>Vault settings</strong>. To change a pattern, confirm the current one, then enter the new one twice. If you forgot the pattern, use <strong>Recover vault</strong> on the lock screen and supply that vault’s recovery phrase to choose a replacement. Repeated incorrect attempts cause a cooldown.</p><p>To generate or replace a recovery phrase, use the Recovery section, save the new phrase externally, repeat it, and confirm the current pattern. Generated phrases are recommended. A replacement invalidates the old phrase for local recovery immediately. For an existing iCloud backup, the change takes effect after the next backup completes; an already exported file always requires its original phrase.</p><p><strong>Pattern grid</strong> changes the grid for every vault. Choose a size and follow the wizard for each vault: confirm its old pattern, then draw a unique new pattern twice. Biometric authentication is also required if any vault uses it. Review and save. Cancelling leaves the existing grid and patterns unchanged; a successful change locks open vault windows.</p><div class="callout"><strong>Recovery is not a backup.</strong> Resetting a pattern helps open files still on the device. Recovering deleted files requires a saved backup as well as the correct phrase.</div>'''),
section('icloud-backup', '8. Back up to iCloud', '''<ol><li>Open the owned vault, then <strong>Settings → Encrypted iCloud backup</strong>.</li><li>Enter its recovery phrase and choose <strong>Enable iCloud backup</strong>.</li><li>Keep the vault open with internet access and enough iCloud storage. Wait for a <strong>Last completed backup</strong> date.</li><li>Use <strong>Back up now</strong> for a fresh copy before switching devices or removing the app. Reopen the vault to retry an interrupted upload.</li></ol><p>Each vault opts in separately. The app keeps one latest completed cloud backup, without historical versions. Backups run in the foreground; this is not two-way sync between your devices.</p><p><strong>Turn off and delete cloud backup</strong> stops future backup and requests removal of that configured cloud copy. Your local files remain. If removal is pending, reconnect with the same iCloud account and let the app retry.</p>'''),
section('restore', '9. Restore from iCloud', '''<ol><li>Sign in to the Apple Account that owns the backup.</li><li>Choose <strong>Restore from iCloud</strong> during onboarding, on the lock screen, or in backup settings.</li><li>Choose a dated backup and enter the phrase valid for its latest completed upload.</li><li>Open the backup, choose a unique local vault name, and set a new pattern.</li><li>After restoration, set up a new recovery phrase and enable future backup again if desired.</li></ol><p>Restoration creates a new vault and does not overwrite another one. Names are encrypted, so the initial list identifies backups by date. Free limits are checked before installation; an oversized backup is not silently truncated.</p><p>A pattern alone cannot restore deleted media. A recovery phrase without a completed backup cannot recreate it either.</p>'''),
section('file-backup', '10. Export or import an encrypted backup file', '''<p>For a portable archive, open <strong>Settings → File backup → Export backup file</strong>, enter the recovery phrase, and save the <code>.patternbackup</code> file through Files. Store the file and phrase separately. If you save to iCloud Drive or another cloud provider, wait for that provider’s upload to finish.</p><p>A file backup is a snapshot: export again to include later changes. To restore it, choose <strong>Import a backup file</strong>, select the archive, enter the phrase used when it was created, and follow the new-vault setup. Changing the app’s current recovery phrase does not rewrite existing archive files.</p>'''),
section('share', '11. Share a vault or accept a share', '''<h3>Create a share</h3><ol><li>With Pattern Pro, open the owned vault and choose <strong>Settings → Sharing</strong>.</li><li>Optionally enter a recipient label and set an expiry, maximum opens, export permission, or capture-triggered lock.</li><li>Choose <strong>Create sharing phrase</strong> and wait for the upload to finish.</li><li>Copy and send that phrase privately to the intended recipient. It is separate from both your pattern and recovery phrase. The phrase is not shown again after you leave its display.</li></ol><h3>Accept a share</h3><p>Choose <strong>Join shared vault</strong> in onboarding, on the lock screen, or in settings. Enter the sharing phrase while signed in to iCloud, then choose a local name and pattern. The first claiming Apple Account becomes the recipient. The same account can import again using the original sharing phrase.</p><p>Receiving is free and does not consume owned-vault limits. Received vaults are read-only, require an internet connection to open, and periodically recheck access while open. Owners send updates while their vault is open; recipients receive the available version when reopening.</p><h3>Control or end access</h3><p>Use the owner’s Sharing settings to send updates or <strong>Revoke access</strong>. Revocation takes effect when iCloud receives it. Keep the app installed until pending revocations finish. Open limits are counted per local installation, so removal or reinstallation can reset them. Capture locking reacts to detection and cannot prevent the first screenshot or an external camera. Previously exported copies remain outside Pattern’s control.</p>'''),
section('biometrics', '12. Add Face ID or Touch ID and a dummy vault', '''<p>In settings, open <strong>Face ID &amp; dummy vault</strong> or <strong>Touch ID &amp; dummy vault</strong>. Choose another existing vault as the dummy, enable biometric protection, and follow the pattern and biometric confirmations.</p><p>Your pattern still selects the protected vault. Successful biometrics then open it; the device passcode is not a substitute. A failed, denied, cancelled, or unavailable biometric check displays the chosen dummy instead. A system interruption leaves the app locked.</p><p>A dummy session can use its media but cannot open vault settings or create vaults. Unlock the dummy with its own pattern for full access. If the dummy has been deleted, failed authentication keeps the app locked. <strong>Biometric failure does not activate duress.</strong></p>'''),
section('duress', '13. Understand duress before enabling it', '''<div class="callout warning"><strong>This changes access to your other vaults.</strong> Do not enable or test it on irreplaceable content without a separately saved, usable backup.</div><p><strong>Use a duress vault</strong> arms the current vault’s existing pattern. Setup explains the consequences and requires acknowledgment and pattern confirmation. It does not trigger immediately.</p><p>On a later unlock with that armed pattern:</p><ul><li>The selected dummy survives, or the triggering vault survives if no dummy is selected. When a different dummy survives, the triggering vault also loses access.</li><li>Credentials for every other local vault are removed. Their old patterns and recovery phrases no longer open them in Pattern, although the files remain on disk.</li><li>The surviving vault gets a new recovery phrase. Use <strong>Save new recovery phrase</strong> in its settings and keep it externally.</li><li>Cloud backup, sharing, and manual backups stop on that installation. Owned shares are queued for revocation. Earlier personal cloud backups and separately exported backup files are not erased.</li></ul><p>Turning duress off does not restore removed access or re-enable backups. Restoring a usable independent backup is a separate action. Confirming a pattern inside settings does not activate duress. Duress is not secure erasure or a guarantee that the app’s data cannot be discovered.</p>'''),
section('icons-language', '14. Change the icon or language', '''<p>Open <strong>Settings → App settings → App icon</strong> and select a design. Classic restores the primary icon. The icon applies across all vaults on that device and does not change access or the installed app’s name.</p><p>For a custom launcher name, use the picker’s <strong>Home Screen name → Set up a named shortcut</strong> guide. It helps you create an Apple Shortcuts “Open App → Pattern” launcher with selected artwork. This creates a separate shortcut; it does not rename, hide, or remove the installed app.</p><p>Pattern supports English, Japanese, Korean, French, German, Italian, and Simplified Chinese. Change the app’s language in device Settings where available. Your own names, filenames, and phrase words are not translated.</p>'''),
section('purchases-removal', '15. Purchases, removal, and help', '''<p>Open <strong>Pattern Pro</strong> in vault settings to purchase or restore purchases. It is a one-time unlock. The regular and special-offer purchases grant the same features. Restore purchases with the original Apple Account; it does not restore vault media.</p><p><strong>Delete this vault</strong> requires its name and current pattern. It removes its local content and credentials and, for owned vaults, requests deletion of configured cloud backup and owned shares. Other local vaults, Photos originals, and exported files remain. Removing a received vault removes only its local copy.</p><p>Deleting Pattern removes local vaults and its installation key. Offloading keeps app data. Before deleting, verify a usable backup and complete cloud removals you want performed. See the <a href="faq.html">FAQ</a> or contact {{contact}} for help. Include app/iOS version and the error message, never your secret phrases.</p>''')])

FAQ = [
('basics','Basics',[
('account','Do I need an account?','No Pattern account is required for local vaults. Optional iCloud backup and sharing require an Apple Account signed in to iCloud. Purchases use the App Store.'),
('free','What is free, and what does Pro unlock?','Free use includes three owned vaults with five total items per vault across photos, videos, memos, documents, and folders. Pro is a one-time purchase that removes these limits and enables creating shares. Receiving shares is free and does not consume owned-vault limits. Storage capacity still depends on your device and iCloud plan.'),
('patterns','Does each pattern open a different vault?','Yes. Each registered pattern selects its own vault. Use New vault to register another; entering an unknown pattern does not create one. A folder stays inside its parent vault and has no separate pattern.'),
('grid','Can I change between 3 × 3, 4 × 4, and 5 × 5?','Yes. Pattern grid in settings changes the grid for all vaults together. You must confirm every current pattern and register every replacement before saving. <a href="manual.html#recovery">See the pattern and grid instructions.</a>'),
('subscription','Is Pro a subscription?','No. Both the regular purchase and a special-offer purchase are non-consumable, one-time unlocks with the same features. The price shown by Apple’s purchase flow applies. There is no recurring Pattern subscription.')]),
('files','Files and camera',[
('originals','Does importing delete my originals?','No. Pattern copies selected items. Delete originals from Photos is a separate option after successful import and requires system confirmation. It can affect iCloud Photos and synced devices. Pattern does not empty Recently Deleted. File imports do not delete source documents.'),
('live-photos','What happens to Live Photos?','The current importer saves the still image, not the motion component. Pattern therefore declines automatic deletion of those Live Photo originals. Keep the source if you need the complete Live Photo.'),
('camera-photos','Will the private camera put photos in Photos?','No. Captures go into an app-private review draft. Use saves to the selected vault/folder; Retake or Cancel discards the draft. Backgrounding discards an unconfirmed capture. You can separately choose to export a saved file later.'),
('silent','Why is silent capture unavailable or lower quality?','Silent photos use an ARKit camera frame on supported hardware and cameras, rather than the normal full-resolution still-photo path. This can reduce detail. The speaker toggle applies to photos and does not mute video audio.'),
('search','Why can’t I find an item with search?','Search matches the item or filename within the current library or folder; it does not search inside document text. Check your folder and filter. The All filter includes every item type. Changing folders or adding content clears the query.'),
('folder-delete','Does deleting a folder delete its files?','No. Its items remain in the vault. Deleting selected items is a different action and permanently removes their app copies after confirmation.'),
('metadata','Are dates or location metadata removed?','Not necessarily. Original files can retain embedded metadata, including location information supplied by the source camera. Pattern is not a metadata-removal tool; exported and shared copies may retain that information.')]),
('security','Security and recovery',[
('encryption','Is everything encrypted with my pattern?','No. The pattern is an app access lock. Local files use iOS complete file protection, and the credential record has separate installation-bound encryption. Cloud and portable backup archives are encrypted with AES-256-GCM; their encryption is not derived from the unlock pattern.'),
('forgot','What if I forget my pattern?','Choose Recover vault and use the recovery phrase to set a replacement for that vault. If neither credential is available, support cannot bypass the lock for you. A usable encrypted backup and its original phrase can be restored as a separate vault.'),
('deleted-app','Can a recovery phrase restore files after deleting the app?','Only if a completed cloud backup or a saved .patternbackup archive also exists. A phrase does not contain your files. Local vaults are excluded from ordinary device backups; reinstalling or restoring a purchase does not bring those files back.'),
('changed-phrase','Which phrase opens an older backup?','An exported archive always uses the phrase from when it was created. After you change a recovery phrase, an existing cloud copy continues to use its previous phrase until the next backup completes. The new phrase applies to local recovery immediately.'),
('biometric-dummy','Why did Face ID or Touch ID open a different vault?','When configured, Pattern deliberately opens your chosen dummy vault if biometrics fail, are cancelled, or are unavailable. This alone does not activate duress or change backups. A system interruption leaves the app locked. Unlock the dummy with its own pattern for its full settings.'),
('duress-effect','What does duress actually do?','Unlocking with an armed duress pattern keeps the selected dummy, or the triggering vault if there is no dummy, and removes access credentials for all other local vaults. It rotates the survivor’s recovery phrase, stops backup/sharing, and queues owned-share revocations. Files for revoked vaults remain on disk. Disabling duress does not undo it. <a href="manual.html#duress">Read the full consequences before enabling it.</a>'),
('capture','Can Pattern prevent screenshots?','Not completely. For a shared vault with capture locking enabled, the app can react to capture detection and lock access. It cannot prevent the first screenshot or someone photographing the screen with another camera.')]),
('cloud','Backup and sharing',[
('sync','Does iCloud keep all my devices automatically in sync?','No. Personal cloud backup runs while the relevant vault is open and stores the latest completed copy. Restoration makes an independent local vault. It is not bidirectional device sync and does not maintain historical backup versions.'),
('backup-failure','Why isn’t my backup finishing?','Check internet access, available iCloud/device storage, and that you are signed in to the Apple Account used to set it up. Keep the vault open, tap Back up now, and check the completion date. Reopen to retry interrupted uploads. Record an error message for support, but do not delete the app as a troubleshooting step before verifying a backup.'),
('no-backups','Why is the restore list empty?','You must use the Apple Account that owns a backup, and at least one upload must have completed. Ordinary device backup, iCloud Photos, and exported files in iCloud Drive are different. For a .patternbackup file, choose Import a backup file instead.'),
('shared-offline','Can I open a received vault offline?','No. It requires online access checks before opening and periodically while open. Your own local vaults can be used offline. Exporting from a received vault additionally depends on the owner’s permission.'),
('sharing-phrase','Is a sharing phrase the same as a recovery phrase?','No. Send only the generated sharing phrase to an intended recipient. The first claiming Apple Account becomes the recipient; the same account can import again using that phrase. Your unlock pattern and recovery phrase should remain private.'),
('revoke','Does revocation delete everything the recipient has seen?','No. It prevents further access through the share after iCloud receives the revocation and access is rechecked. It cannot erase exported copies, existing screenshots, or external photographs. Keep Pattern installed until pending revocations complete.'),
('open-limit','Is the open limit enforced across all installations?','No. Open counts are maintained per local installation and survive normal relaunches. Removing the received vault or reinstalling can reset the local counter. Treat this as an app convenience, not protection against a determined recipient.'),
('remove-cloud','How do I delete a cloud backup?','In that vault’s iCloud backup settings, choose Turn off and delete cloud backup. It removes the configured cloud copy when iCloud is available and keeps local files. Deleting the app alone does not remove completed cloud backups. <a href="privacy-policy.html#retention">See the deletion details.</a>')]),
('appearance-help','Appearance, purchases, and help',[
('icon-name','Does changing the icon also rename the app?','No. The installed app stays named Pattern. The App icon screen includes a guide for creating a separately named Home Screen shortcut through Apple Shortcuts. That does not hide or rename the installed app.'),
('restore-purchase','How do I restore Pro?','Open Pattern Pro in settings and choose Restore purchases while using the Apple Account that purchased it. Apple may ask you to sign in. This restores the license, not vault files; use a cloud or file backup to restore content.'),
('refund','How do I request a refund?','For an App Store purchase, follow <a href="https://support.apple.com/en-us/118223">Apple’s refund process</a>. Eligibility depends on the purchase, country or region, and applicable law. A refunded entitlement can remove Pro, while the current app preserves access to existing local content and limits new additions.'),
('help','What should I send to support?','Contact {{contact}} with the app version, iOS/iPadOS version, a description of what happened, and any error message. Redact screenshots. Do not send private vault files, unlock patterns, recovery phrases, sharing phrases, or payment-card details.')])]
PAGES['faq'] = dict(title='Frequently Asked Questions',description='Answers about privacy, recovery, iCloud, sharing, and everyday use.',lead='Quick answers, with links to the steps that help you move forward.',faq=FAQ)
